  'νe': 'neutrinos, three kinds', 'νμ': 'neutrinos, three kinds', 'ντ': 'neutrinos, three kinds', 'electron ν': 'neutrinos, three kinds', 'muon ν': 'neutrinos, three kinds', 'tau ν': 'neutrinos, three kinds', 'sterile ν': 'sterile neutrino', 'pollen': 'ragweed pollen', 'pollen grain': 'ragweed pollen', 'a human hair': 'human hair', 'bacterium': 'e. coli', 'honeybee': 'western honey bee worker', 'nucleus': 'nitrogen-14 nucleus', 'a person': 'average american man', 'a puppy': 'beagle puppy', 'laniakea': 'laniakea supercluster', 'perseus–pisces': 'perseus–pisces supercluster', 'great walls': 'cfa2 great wall', 'city bus': 'new york city bus', 'taxi': 'nyc yellow cab', 'box truck, 26 ft box': 'box truck', 'a building': 'midtown office tower', 'a car': 'sedan', 'fine dust': 'fine dust, pm2.5', 'influenza virus': 'virus',
