export function keyOf(text) {
  let t = String(text).trim().replace(/[‘’]/g, "'");
  if (/^theory · /i.test(t)) t = t.slice(9);
  const parts = t.split(' · ');
  t = parts[0].toLowerCase().replace(/\s+/g, ' ').trim();
  if (/^[\d.,×⁰¹²³⁴⁵⁶⁷⁸⁹⁻\- ]+ (million |billion )?light-(years?|days?|months?)$/.test(t)) return 'light-year';
  if (/^[\d.,×⁰¹²³⁴⁵⁶⁷⁸⁹⁻\- ]+ (million |billion )?(metres?|km|au|centimetres?|millimetres?|micrometres?|nanometres?|picometres?|femtometres?|attometres?)$/.test(t)) return 'ruler';
  t = ALIASES[t] || ALIASES[t.replace(/'/g, '’')] || t;
  return t;
}

// The note for a label, or a short one made from the label itself (a star or galaxy without its own).
export function noteFor(text, galaxies = []) {
  const key = keyOf(text), parts = String(text).split(' · '), tail = parts.length > 1 ? parts.slice(1).join(' · ') : '';
  if (NOTES[key]) {
    const n = NOTES[key], facts = [...n.facts];
    if (tail && /\d/.test(tail) && !facts.some(f => f[1] === tail)) facts.unshift(['In the frame', tail]);
    return { key, ...n, facts };
  }
  for (const st of [', nj', ', ny']) if (NOTES[key + ' county' + st]) return { key: key + ' county' + st, ...NOTES[key + ' county' + st] };
  const county = /^(.*) county, (nj|ny)$/.exec(key);
  if (county) { const state = county[2] === 'nj' ? 'New Jersey' : 'New York', nm = county[1].replace(/\b\w/g, c => c.toUpperCase()); return { key, title: `${nm} County, ${state}`, kind: 'Measured', body: [`A county of ${state}, drawn from the Census Bureau’s 2023 outlines.`], read: [wiki(`${nm.replace(/ /g, '_')}_County,_${state.replace(' ', '_')}`)], facts: [] }; }
  const name = parts[0].trim(), g = galaxies.find(x => x.name === name);
  if (g) return { key, title: name, kind: 'Measured', body: [`A ${g.kind === 'E' ? 'elliptical' : g.kind === 'S' ? 'spiral' : 'dwarf or irregular'} galaxy ${tail ? tail.replace('ly', 'light-years') + ' away' : ''}, drawn at its measured direction and distance${g.size ? ' and about its measured size' : ''}.`], read: [search(name, 'galaxy')], facts: tail ? [['Distance', tail]] : [] };
  if (/ ly$/.test(tail)) return { key, title: name, kind: 'Measured', body: [`A star ${tail.replace(' ly', ' light-years')} away, drawn at its measured direction and distance. Stars this far out are among the brighter ones in our night sky.`], read: [search(name, 'star')], facts: [['Distance', tail]] };
  return null;
}

